//! The VTU reader against files it did not write. The fixtures were generated by a stand-alone Python
//! script (standard library only) from the VTK file-format documentation: two tetrahedra with a
//! Float32 point field and a Float64 cell field, in every payload layout VTK writers use.

use heartsim_geometry::bridge::vtk::parse_vtu;

const FIXTURES: [(&str, &[u8]); 6] = [
    ("inline_u32", include_bytes!("fixtures/inline_u32.vtu")),
    ("inline_zlib_u64", include_bytes!("fixtures/inline_zlib_u64.vtu")),
    (
        "appended_raw_u64",
        include_bytes!("fixtures/appended_raw_u64.vtu"),
    ),
    (
        "appended_raw_zlib_u32",
        include_bytes!("fixtures/appended_raw_zlib_u32.vtu"),
    ),
    (
        "appended_base64_u32",
        include_bytes!("fixtures/appended_base64_u32.vtu"),
    ),
    (
        "appended_base64_zlib_u64",
        include_bytes!("fixtures/appended_base64_zlib_u64.vtu"),
    ),
];

#[test]
fn every_payload_layout_decodes_to_the_same_grid() {
    for (name, bytes) in FIXTURES {
        let g = parse_vtu(bytes).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(g.points.len(), 5, "{name}");
        assert_eq!(g.points[4], [1000.0, 1000.0, 1000.0], "{name}");
        assert_eq!(g.connectivity, vec![0, 1, 2, 3, 1, 2, 3, 4], "{name}");
        assert_eq!(g.offsets, vec![0, 4, 8], "{name}");
        assert_eq!(g.point_fields[0].name, "Vm", "{name}");
        assert_eq!(
            g.point_fields[0].data,
            vec![-85.0, -40.0, 0.0, 20.0, 35.5],
            "{name}"
        );
        assert_eq!(g.cell_fields[0].name, "Scalars_", "{name}");
        assert_eq!(g.cell_fields[0].data, vec![12.5, -7.25], "{name}");
        assert_eq!(g.cell_centres()[0], [250.0, 250.0, 250.0], "{name}");
    }
}
